extends CharacterBody2D

signal hp_changed(current: float, max_hp: float)
@export var speed: float = 200.0
@export var max_hp := 100.0
@export var fire_interval := 0.4
@export var projectile_scene: PackedScene = preload("res://Projectile.tscn")
@export var projectile_damage := 10.0
@export var contact_damage := 10
@export var contact_tick := 0.5
var _can_fire := true
var hp := 100.0
var spawn_pos: Vector2
var _touching_enemies := 0
var _damage_loop_running := false
var is_dead := false


@onready var hurtbox: Area2D = $Hurtbox
@onready var spell_caster_node: Node = $SpellCaster
@onready var spell_caster: SpellCaster = $SpellCaster as SpellCaster

func _ready():
	
	add_to_group("player")
	print("PLAYER READY + GROUP ADDED")
	hp = max_hp
	spawn_pos = global_position
	hp_changed.emit(hp, max_hp) # initial update
	if not hurtbox.area_entered.is_connected(_on_hurtbox_area_entered):
		hurtbox.area_entered.connect(_on_hurtbox_area_entered)
	if not hurtbox.area_exited.is_connected(_on_hurtbox_area_exited):
		hurtbox.area_exited.connect(_on_hurtbox_area_exited)
	print("PLAYER READY, HP=", hp)
	if spell_caster:
		spell_caster.setup(self)
	else:
		push_warning("SpellCaster node not found!")
	print("SpellCaster node type:", spell_caster_node.get_class())
	print("SpellCaster script:", spell_caster_node.get_script())
	print("SpellCaster is SpellCaster class?:", spell_caster != null)
	if $SpellCaster.get_script() == null:
		$SpellCaster.set_script(load("res://SpellCaster.gd"))
		print("FORCED SpellCaster.gd onto SpellCaster node")

	# now re-fetch typed reference
	spell_caster = $SpellCaster as SpellCaster
	if spell_caster == null:
		push_error("SpellCaster still not typed. Check path/script file.")
		return

	spell_caster.setup(self)

func _physics_process(delta):
	var dir := Input.get_vector("ui_left","ui_right","ui_up","ui_down")
	velocity = dir * speed
	move_and_slide()
	
	if dir != Vector2.ZERO:
		rotation = dir.angle()

func _on_hurtbox_area_entered(area: Area2D) -> void:
	print("HURTBOX ENTERED BY:", area.name, " groups:", area.get_groups())
	print("AREA:", area.name)
	print("IN GROUP enemy_hitbox?", area.is_in_group("enemy_hitbox"))
	print("GROUPS:", area.get_groups())
	# We'll tag enemy hitboxes with a group
	if area.is_in_group("enemy_hitbox"):
		_touching_enemies += 1
		_start_contact_loop()
		_take_damage(10)
	if area.is_in_group("player_projectile"):
		return	

func _on_hurtbox_area_exited(area: Area2D) -> void:
	if area.is_in_group("enemy_hitbox"):
		_touching_enemies = max(_touching_enemies - 1, 0)
		
func _start_contact_loop() -> void:
	if _damage_loop_running:
		return
	_damage_loop_running = true

	while _touching_enemies > 0 and hp > 0:
		_take_damage(contact_damage)
		await get_tree().create_timer(contact_tick).timeout

	_damage_loop_running = false

func _take_damage(amount: float) -> void:
	if is_dead:
		return
	hp = max(hp - amount, 0)
	hp_changed.emit(hp, max_hp)
	print("DAMAGE!", amount, "HP NOW:", hp)
	if hp <= 0:
		die()	

func _process(_delta):
	# use _process for timers/spawning; physics ok too but this is fine
	if _can_fire:
		_auto_attack()

func _auto_attack() -> void:
	var target := _get_nearest_enemy()
	if target == null:
		return

	_can_fire = false

	var proj = projectile_scene.instantiate()
	proj.global_position = global_position
	proj.damage = projectile_damage

	var dir := (target.global_position - global_position).normalized()
	proj.velocity = dir * proj.speed

	get_tree().current_scene.add_child(proj)

	await get_tree().create_timer(fire_interval).timeout
	_can_fire = true

func _unhandled_input(event):
	if event is InputEventMouseButton and event.button_index == MOUSE_BUTTON_LEFT and event.pressed:
		spell_caster.cast_all_manual()

func die() -> void:
	if is_dead:
		return
	is_dead = true

	Global.add_followers(-10)

	if Global.followers > 0:
		respawn()
	else:
		get_tree().current_scene.call_deferred("end_run")

func respawn() -> void:
	hp = max_hp
	hp_changed.emit(hp, max_hp)
	global_position = spawn_pos
	is_dead = false

func _get_nearest_enemy() -> Node2D:
	var enemies := get_tree().get_nodes_in_group("enemies")
	var best: Node2D = null
	var best_dist := INF

	for e in enemies:
		if e == null or !is_instance_valid(e):
			continue
		var d := global_position.distance_squared_to(e.global_position)
		if d < best_dist:
			best_dist = d
			best = e

	return best

func end_run() -> void:
	print("GAME OVER")
	get_tree().paused = true
